test("data types check via bru var", function() {
  let v = bru.getVar("dataTypeVarTest");
  v = {
    ...v,
    "undefined": undefined
  };
  expect(v).to.eql({
    "boolean": false,
    "number": 1,
    "string": "bruno",
    "array": [1, 2, 3, 4, 5],
    "object": {
      "hello": "bruno"
    },
    "null": null,
    "undefined": undefined
  })
});
